import React, { useEffect, useState } from "react";
import PropTypes from "prop-types";
import { database } from "../../firebase";
import { ref, onValue, update, off, get, child } from "firebase/database";
import "./AddressEditor.css";

export default function AddressEditor({ userID, uniqueKey, onDone }) {
  const recordPath = `data/scans/${userID}/${uniqueKey}`;
  const addressRef = ref(database, `${recordPath}/googleMapAddress`);
  const parentRef = ref(database, recordPath);

  const [loading, setLoading] = useState(true);
  const [originalAddress, setOriginalAddress] = useState("");
  const [editedAddress, setEditedAddress] = useState("");
  const [status, setStatus] = useState(null); // 'saving', 'validating', 'saved', 'error'
  const [validationError, setValidationError] = useState(null);
  const [isDeleted, setIsDeleted] = useState(false);

  // Listen for initial address
  useEffect(() => {
    const unsubscribe = onValue(addressRef, (snap) => {
      const val = snap.val();

      if (val) {
        setOriginalAddress(val);
        // Only set the edited address if the user hasn't typed anything yet
        setEditedAddress((prev) => (prev && prev.length ? prev : val));
        setLoading(false);
        setIsDeleted(false);
        return;
      }

      // If we were processing and the value disappears, it means it was deleted
      if (status === "validating" || status === "saving" || status === "error") {
        setLoading(false);
        setIsDeleted(true);
        return;
      }

      setLoading(true);
      setOriginalAddress("");
    });

    return () => {
      off(addressRef);
      if (typeof unsubscribe === "function") {
        unsubscribe();
      }
    };
  }, [addressRef, status]);

  // Listen for validation status changes OR deletion
  useEffect(() => {
    // We care about deletion if we are validating/saving OR if we already detected deletion
    if (status !== "validating" && !isDeleted) return;

    const unsubscribe = onValue(parentRef, async (snap) => {
      const data = snap.val();

      // If data is null, record is deleted
      if (!data) {
        setIsDeleted(true);
        setStatus("error");

        // Fetch specific error from temp location
        try {
          const tempRecordRef = ref(database, `data/temp/${userID}/${uniqueKey}`);
          const tempSnap = await get(tempRecordRef);

          if (tempSnap.exists()) {
            const tempData = tempSnap.val();
            if (tempData.uspsValidationError || tempData.error) {
              setValidationError(tempData.uspsValidationError || tempData.error);
              return;
            }
          }

          // Fallback
          setValidationError("Scan rejected or deleted during validation.");
        } catch (err) {
          console.error("Error fetching temp data:", err);
          setValidationError("Validation failed and record was removed.");
        }
        return;
      }

      // Check if validation is still pending
      if (data.uspsValidationPending === true) {
        return; // Still waiting
      }

      // Check for errors (in existing record)
      if (data.uspsValidationError) {
        setStatus("error");
        setValidationError(data.uspsValidationError);
        return;
      }

      // Check for duplicates (in existing record)
      if (data.duplicateAddress === true) {
        setStatus("error");
        setValidationError("This address has already been scanned for this campaign.");
        return;
      }

      // Success case
      if (data.uspsValidated === true || data.duplicateAddressDifferentCampaign === true) {
        finishSave();
      }
    });

    return () => {
      off(parentRef);
      unsubscribe();
    };
  }, [status, parentRef, userID, uniqueKey, isDeleted]);

  const writeAddedToMauticFalse = async (fields = {}) => {
    // Critical: Only writing this triggers the Mautic update / USPS validation
    const payload = { ...fields, addedToMautic: false, uspsValidationPending: true, uspsValidationError: null };
    return update(parentRef, payload);
  };

  const handleSave = async () => {
    setStatus("saving");
    setValidationError(null);

    try {
      // 1. Save the Address / Mautic flag
      if (!editedAddress || editedAddress === originalAddress) {
        await writeAddedToMauticFalse({});
      } else {
        await writeAddedToMauticFalse({ editedAddress });
      }

      setStatus("validating");
      // The useEffect hook will handle the rest based on DB changes

    } catch (err) {
      console.error("Failed to save:", err);
      setStatus("error");
      setValidationError("Failed to save address. Please try again.");
    }
  };

  const finishSave = async () => {
    setStatus("saved"); // Will prevent error view from showing momentarily

    try {
      // 2. Check DB for image existence before finishing
      const imageSnapshot = await get(child(parentRef, "urlToReadImage"));
      const hasImage = imageSnapshot.exists() && !!imageSnapshot.val();

      // 3. Complete logic
      setTimeout(() => {
        if (typeof onDone === "function") {
          onDone(hasImage);
        }
      }, 600);
    } catch (err) {
      console.error("Failed to check image status:", err);
      // Even if check fails, try to proceed? Or show error?
      // If record exists (success case), we should proceed.
      // If checking image fails, let's just assume no image to be safe or retry?
      // For now, show error.
      setStatus("error");
      setValidationError("Failed to verify image status.");
    }
  };

  // Dedicated Error View
  if (status === "error" || (isDeleted && validationError)) {
    return (
      <div className="address-editor">
        <div className="ae-error-container">
          <div className="ae-error-box">
            <div className="ae-error-message">
              {validationError || "An error occurred during validation."}
            </div>
            <button
              className="ae-retry-button"
              onClick={() => onDone?.(null)}
            >
              Scan Again
            </button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="address-editor">
      <h2 className="ae-title">Confirm / Edit Address</h2>

      {loading && (
        <div className="ae-loading">
          Waiting for address from Google Maps...
        </div>
      )}

      {!loading && (
        <>
          <label className="ae-label">Address detected from Google:</label>
          <div className="ae-original">{originalAddress}</div>

          <label className="ae-label">Edit address :</label>
          <textarea
            className="ae-textarea"
            value={editedAddress}
            onChange={(e) => setEditedAddress(e.target.value)}
            rows={4}
            aria-label="Edit address"
            disabled={status === "saving" || status === "validating"}
          />

          <div className="ae-actions">
            <button
              className="ae-button"
              onClick={handleSave}
              disabled={status === "saving" || status === "validating" || status === "saved"}
            >
              {status === "saving" ? "Saving..." :
                status === "validating" ? "Validating Address..." :
                  "Save & Confirm Address"}
            </button>
            <button
              className="ae-button"
              onClick={() => onDone?.(null)}
              disabled={status === "saving" || status === "validating"}
              style={{
                marginTop: "10px",
                marginBottom: "20px",
                backgroundColor: "#757575",
                borderColor: "#757575"
              }}
            >
              Back to Dashboard
            </button>
          </div>

          {status === "saved" && (
            <div className="ae-status ae-status-success">
              Address Verified! Moving...
            </div>
          )}

          {status === "validating" && (
            <div className="ae-status ae-status-validating">
              Verifying address with USPS...
            </div>
          )}
        </>
      )}
    </div>
  );
}

/* =======================
   PropTypes validation
   ======================= */

AddressEditor.propTypes = {
  userID: PropTypes.string.isRequired,
  uniqueKey: PropTypes.string.isRequired,
  onDone: PropTypes.func,
};