/**
 * confidence-utils.js
 *
 * Pure helpers for computing GPS delivery confidence level.
 *
 * Accuracy tiers:
 *   Good     — both coordAccuracy AND photoAccuracy are ≤ GOOD_ACCURACY_THRESHOLD
 *   Poor     — both coordAccuracy AND photoAccuracy are > POOR_ACCURACY_THRESHOLD
 *   Moderate — everything in between (at least one is OK)
 *
 * Distance tiers:
 *   Low      — distance ≤ MAX_ACCEPTABLE_DISTANCE
 *   High     — distance >  MAX_ACCEPTABLE_DISTANCE
 */

export const MAX_ACCEPTABLE_DISTANCE_DEFAULT = 5;   // metres — fallback / USA
export const MAX_ACCEPTABLE_DISTANCE_INDIA = 15;  // metres — India
export const GOOD_ACCURACY_THRESHOLD = 30;  // metres — both readings must be within this
export const POOR_ACCURACY_THRESHOLD = 100; // metres — both readings must exceed this

/**
 * Returns the acceptable scan-to-photo distance for the given coordinates.
 * Based on bounding boxes:
 *   India: lat 8–37, lon 68–97  → 15 m (GPS less reliable in dense urban areas)
 *   USA:   lat 24–50, lon -125 to -66 → 5 m
 *   Others: 5 m (default)
 *
 * @param {number} lat
 * @param {number} lon
 * @returns {number} max acceptable distance in metres
 */
export function getMaxAcceptableDistance(lat, lon) {
    // India — includes mainland + island territories (Lakshadweep, Andaman & Nicobar)
    if (lat >= 6.5 && lat <= 38 && lon >= 68 && lon <= 98) {
        return MAX_ACCEPTABLE_DISTANCE_INDIA;
    }
    // USA — full country: contiguous 48 + Alaska (up to 72°N) + Hawaii (down to 18°N)
    if (lat >= 18 && lat <= 72 && lon >= -179 && lon <= -66) {
        return MAX_ACCEPTABLE_DISTANCE_DEFAULT;
    }
    return MAX_ACCEPTABLE_DISTANCE_DEFAULT;
}

/**
 * @param {number} coordAccuracy   - accuracy (m) at scan time
 * @param {number} photoAccuracy   - accuracy (m) at photo time
 * @returns {"good"|"moderate"|"poor"}
 */
export function getAccuracyTier(coordAccuracy, photoAccuracy) {
    const bothGood = coordAccuracy <= GOOD_ACCURACY_THRESHOLD &&
        photoAccuracy <= GOOD_ACCURACY_THRESHOLD;
    const bothPoor = coordAccuracy > POOR_ACCURACY_THRESHOLD &&
        photoAccuracy > POOR_ACCURACY_THRESHOLD;

    if (bothGood) return "good";
    if (bothPoor) return "poor";
    return "moderate";
}

/**
 * @param {number} distanceMetres
 * @param {number} [threshold] - max acceptable distance (use getMaxAcceptableDistance)
 * @returns {"low"|"high"}
 */
export function getDistanceTier(distanceMetres, threshold = MAX_ACCEPTABLE_DISTANCE_DEFAULT) {
    return distanceMetres <= threshold ? "low" : "high";
}

/**
 * Truth table from spec:
 *
 * | distance | accuracy | level  | action         | flag  |
 * |----------|----------|--------|----------------|-------|
 * | low      | good     | High   | accept         | false |
 * | low      | moderate | Medium | accept_log     | true  |
 * | low      | poor     | Low    | flag           | true  |
 * | high     | good     | High   | reject         | true  |
 * | high     | moderate | Low    | reject_review  | true  |
 * | high     | poor     | Low    | reject_flag    | true  |
 *
 * Note: "reject" here means warn + flag — the upload is NEVER blocked.
 *
 * @param {"low"|"high"} distanceTier
 * @param {"good"|"moderate"|"poor"} accuracyTier
 * @returns {{ level: "High"|"Medium"|"Low", action: string, flag: boolean }}
 */
export function computeConfidence(distanceTier, accuracyTier) {
    if (distanceTier === "low") {
        if (accuracyTier === "good") return { level: "High", action: "accept", flag: false };
        if (accuracyTier === "moderate") return { level: "Medium", action: "accept_log", flag: true };
    /* poor */                       return { level: "Low", action: "flag", flag: true };
    }
    /* high distance */
    // Good GPS + far distance = GPS *confirms* wrong location → High confidence in the rejection
    if (accuracyTier === "good") return { level: "High", action: "reject", flag: true };
    if (accuracyTier === "moderate") return { level: "Low", action: "reject_review", flag: true };
  /* poor */                         return { level: "Low", action: "reject_flag", flag: true };
}

/**
 * Convenience: compute everything at once.
 *
 * @param {number} distanceMetres
 * @param {number} coordAccuracy
 * @param {number} photoAccuracy
 * @param {number} [originLat]  - latitude of the original scan (used to pick distance threshold)
 * @param {number} [originLon]  - longitude of the original scan
 * @returns {{ distanceTier, accuracyTier, level, action, flag, threshold }}
 */
export function evaluateDeliveryConfidence(distanceMetres, coordAccuracy, photoAccuracy, originLat, originLon) {
    const threshold = (originLat != null && originLon != null)
        ? getMaxAcceptableDistance(originLat, originLon)
        : MAX_ACCEPTABLE_DISTANCE_DEFAULT;
    const distanceTier = getDistanceTier(distanceMetres, threshold);
    const accuracyTier = getAccuracyTier(coordAccuracy, photoAccuracy);
    const result = computeConfidence(distanceTier, accuracyTier);
    return { distanceTier, accuracyTier, threshold, ...result };
}
