import React, { useEffect, useRef, useState } from "react";
import PropTypes from "prop-types";
import { database } from "../../firebase";
import { ref, onValue, update, off, get } from "firebase/database";
import "./PhotoCapture.css";
import { idbPut, idbDelete } from "./indexeddb";
import { resizeAndCompressImage } from "./image-compress";
import { MAX_WIDTH, MAX_HEIGHT, JPEG_QUALITY } from "./config.state";
import { uploadToSignedUrl } from "./upload-to-signed-url";
import { getDistance } from "geolib";
import { evaluateDeliveryConfidence } from "./confidence-utils";

// Map full level names → single-char codes stored in RTDB
const CONF_CODE = { High: "H", Medium: "M", Low: "L" };

export default function PhotoCapture({ userID, uniqueKey, onDone, onPhotoDone }) {
  const recordPath = `data/scans/${userID}/${uniqueKey}`;
  const parentRef = ref(database, recordPath);

  const fileInputRef = useRef(null);
  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const streamRef = useRef(null);
  const signedUrlListenerRef = useRef(null);
  const lastCompressedRef = useRef(null);
  const lastFilenameRef = useRef(null);

  const [loading, setLoading] = useState(true);
  const [status, setStatus] = useState(null);
  const [errorMsg, setErrorMsg] = useState(null);
  const [cameraOpen, setCameraOpen] = useState(false);
  const [scanAddress, setScanAddress] = useState("");
  const [capturedImagePreview, setCapturedImagePreview] = useState(null);
  const [capturedFile, setCapturedFile] = useState(null);
  const [capturedLocation, setCapturedLocation] = useState(null);
  // Full confidence result from the location check
  const [confidenceResult, setConfidenceResult] = useState(null);

  useEffect(() => {
    const fetchAddress = async () => {
      try {
        const snapshot = await get(parentRef);
        if (snapshot.exists()) {
          const data = snapshot.val();
          const addr = data.editedAddress || data.googleMapAddress || "Unknown location";
          setScanAddress(addr);
        }
      } catch (err) {
        console.error("Failed to fetch address:", err);
      }
    };

    fetchAddress();
    setLoading(false);
    return () => {
      cleanupSignedUrlListener();
      stopCamera();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [userID, uniqueKey]);

  const isMobile = () => /Mobi|Android/i.test(navigator.userAgent || "");

  /* ---------------- LOCATION ---------------- */

  /**
   * Get current GPS position. Throws if unavailable or denied.
   * High accuracy required — we don't accept network-only fallback.
   */
  const getCurrentLocation = () =>
    new Promise((resolve, reject) => {
      if (!navigator.geolocation) {
        reject(new Error("GPS_NOT_SUPPORTED"));
        return;
      }
      navigator.geolocation.getCurrentPosition(
        (pos) => resolve({
          x: pos.coords.latitude,
          y: pos.coords.longitude,
          acc: pos.coords.accuracy,   // stored as photoCoords.acc
        }),
        (err) => {
          if (err.code === 1) reject(new Error("GPS_DENIED"));
          else reject(new Error("GPS_UNAVAILABLE"));
        },
        { enableHighAccuracy: true, timeout: 10000, maximumAge: 0 }
      );
    });

  /**
   * Fetch original scan coords (including acc) from DB, get current GPS,
   * compute distance + confidence.
   *
   * Throws GPS_DENIED / GPS_UNAVAILABLE so the caller can block the camera.
   * Returns null only if origin coords are missing (non-GPS failure — still allowed).
   */
  const checkLocationConfidence = async () => {
    const coordsSnap = await get(ref(database, `${recordPath}/coordinates`));
    const origin = coordsSnap.val(); // { x, y, acc }

    // GPS must be on — throws if denied/unavailable
    const current = await getCurrentLocation();

    if (!origin || !isFinite(origin.x) || !isFinite(origin.y)) {
      // Origin missing — can't compare, store photo coords only, no trustScore
      return { photoCoords: current };
    }

    const dist = getDistance(
      { latitude: origin.x, longitude: origin.y },
      { latitude: current.x, longitude: current.y }
    );

    const coordAcc = isFinite(origin.acc) ? origin.acc : 999;
    const photoAcc = current.acc;

    console.log(`Distance: ${dist}m | scanAcc: ±${coordAcc}m | photoAcc: ±${photoAcc}m`);

    const evaluation = evaluateDeliveryConfidence(dist, coordAcc, photoAcc, origin.x, origin.y);

    return {
      photoCoords: current,
      distanceMetres: Math.round(dist),
      coordAcc: Math.round(coordAcc),
      evaluation,
    };
  };

  /* ---------------- CAMERA FLOW ---------------- */

  const triggerFileInput = () => {
    if (fileInputRef.current) fileInputRef.current.click();
  };

  const openPicker = async () => {
    setStatus(null);
    setErrorMsg(null);
    setConfidenceResult(null);

    let locationResult = null;
    try {
      locationResult = await checkLocationConfidence();
      setConfidenceResult(locationResult);
    } catch (err) {
      // GPS errors block the camera — all others are non-fatal
      if (err.message === "GPS_DENIED") {
        setStatus("error");
        setErrorMsg(
          "GPS / Location is turned off or blocked.\n\n" +
          "Please enable Location access:\n" +
          "1. Tap the 🔒 Lock icon in your browser address bar.\n" +
          "2. Set Location → Allow.\n" +
          "3. Then tap Open Camera again."
        );
        return;
      }
      if (err.message === "GPS_NOT_SUPPORTED") {
        setStatus("error");
        setErrorMsg("Your device does not support GPS. Cannot take photo.");
        return;
      }
      // GPS_UNAVAILABLE (timeout etc.) — warn but allow
      console.warn("GPS unavailable:", err.message);
      setConfidenceResult(null);
    }

    if (isMobile()) {
      triggerFileInput();
      return;
    }

    if (navigator.mediaDevices?.getUserMedia) {
      try {
        await openCameraInPage();
      } catch {
        triggerFileInput();
      }
      return;
    }

    triggerFileInput();
  };

  async function openCameraInPage() {
    if (cameraOpen) return;
    const stream = await navigator.mediaDevices.getUserMedia({
      video: { width: { ideal: 1280 }, height: { ideal: 720 }, facingMode: "environment" },
    });
    streamRef.current = stream;
    videoRef.current.srcObject = stream;
    await videoRef.current.play();
    setCameraOpen(true);
  }

  function stopCamera() {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach((t) => t.stop());
      streamRef.current = null;
    }
    setCameraOpen(false);
  }

  /* ---------------- CAPTURE + UPLOAD ---------------- */

  const captureFromCamera = async () => {
    const video = videoRef.current;
    const canvas = canvasRef.current;
    if (!video || !canvas) return;

    const vw = video.videoWidth || 1280;
    const vh = video.videoHeight || 720;
    const MAX_CAP = 1280;
    let cw = vw, ch = vh;
    if (vw > MAX_CAP || vh > MAX_CAP) {
      const asp = vw / vh;
      if (asp > 1) { cw = MAX_CAP; ch = Math.round(MAX_CAP / asp); }
      else { ch = MAX_CAP; cw = Math.round(MAX_CAP * asp); }
    }
    canvas.width = cw;
    canvas.height = ch;
    canvas.getContext("2d").drawImage(video, 0, 0, cw, ch);

    setCapturedImagePreview(canvas.toDataURL("image/jpeg", 0.8));

    // Re-capture location at shutter time for maximum accuracy
    try {
      const loc = await getCurrentLocation();
      setCapturedLocation(loc);
    } catch (e) {
      // Use location already captured during openPicker if this fails
      if (confidenceResult?.photoCoords) {
        setCapturedLocation(confidenceResult.photoCoords);
      }
      console.warn("Failed to re-capture location at shutter:", e.message);
    }

    canvas.toBlob((blob) => {
      if (!blob) return;
      const file = new File([blob], `${userID}_${uniqueKey}_${Date.now()}.jpg`, { type: "image/jpeg" });
      setCapturedFile(file);
      stopCamera();
    }, "image/jpeg", 0.8);
  };

  const handleUploadPhoto = async () => {
    if (!capturedFile) return;
    await processFile(capturedFile);
  };

  const processFile = async (file) => {
    setStatus("saving");
    setErrorMsg(null);

    try {
      const compressed = await resizeAndCompressImage(file, MAX_WIDTH, MAX_HEIGHT, JPEG_QUALITY);
      const filename = `${userID}_${uniqueKey}_${Date.now()}.jpg`;
      await idbPut(filename, compressed);
      lastCompressedRef.current = compressed;
      lastFilenameRef.current = filename;

      const updatePayload = { requestToUpload: 1 };

      // Photo coords (location at shutter time) — acc embedded
      const photoLoc = capturedLocation || confidenceResult?.photoCoords;
      if (photoLoc) {
        updatePayload.photoCoords = {
          x: photoLoc.x,
          y: photoLoc.y,
          acc: photoLoc.acc ?? null,
        };
      }

      // Trust score — compact representation
      if (confidenceResult?.evaluation) {
        const { level, action, distanceTier } = confidenceResult.evaluation;
        updatePayload.trustScore = {
          dist: confidenceResult.distanceMetres,     // integer metres
          conf: CONF_CODE[level] ?? level,            // "H" | "M" | "L"
          // only store distTier when it adds value (non-obvious from dist)
          ...(distanceTier === "high" ? { hi: true } : {}),
        };
      }

      await update(parentRef, updatePayload);
      setStatus("waiting-for-signed-url");
    } catch (err) {
      setStatus("error");
      setErrorMsg(err.message);
      return;
    }

    cleanupSignedUrlListener();

    signedUrlListenerRef.current = attachSignedUrlListener(async (url) => {
      if (!lastCompressedRef.current) return;
      setStatus("uploading");
      await uploadToSignedUrl(url, lastCompressedRef.current);
      await update(parentRef, { updateTimestamp: Date.now() });
      setStatus("uploaded");
      await idbDelete(lastFilenameRef.current).catch(() => { });
      setTimeout(callDoneCallback, 300);
    });
  };

  const handleFileSelect = async (file) => {
    if (!file) return;
    setCapturedFile(file);
    try {
      const loc = await getCurrentLocation();
      setCapturedLocation(loc);
    } catch (e) {
      if (confidenceResult?.photoCoords) setCapturedLocation(confidenceResult.photoCoords);
      console.warn("Failed to capture location on file select:", e.message);
    }
    const reader = new FileReader();
    reader.onloadend = () => setCapturedImagePreview(reader.result);
    reader.readAsDataURL(file);
  };

  /* ---------------- HELPERS ---------------- */

  function attachSignedUrlListener(cb) {
    const signedRef = ref(database, `${recordPath}/signedUrlToUploadImage`);
    const unsub = onValue(signedRef, (snap) => snap.val() && cb(snap.val()));
    return () => off(signedRef) || unsub?.();
  }

  function cleanupSignedUrlListener() {
    signedUrlListenerRef.current?.();
    signedUrlListenerRef.current = null;
  }

  const callDoneCallback = () => onPhotoDone?.() || onDone?.();

  const handleTryAgain = () => {
    setStatus(null);
    setErrorMsg(null);
    setConfidenceResult(null);
  };

  /* ---------------- CONFIDENCE WARNING BANNER ---------------- */

  const renderConfidenceBanner = () => {
    if (!confidenceResult?.evaluation) return null;
    const { level, flag, action } = confidenceResult.evaluation;
    // Only suppress banner for the clean "accept" case (Low distance + Good accuracy)
    if (!flag) return null;

    const isReject = action === "reject";           // High+Good: GPS confirms wrong place
    const isLow = level === "Low" && !isReject;  // all other flagged Low cases

    const dist = confidenceResult.distanceMetres ?? "?";
    const scanAcc = confidenceResult.coordAcc ?? null;
    const photoAcc = confidenceResult.photoCoords?.acc != null ? Math.round(confidenceResult.photoCoords.acc) : null;

    let message;
    if (isReject) {
      // High confidence + High distance: GPS is reliable and confirms wrong location
      message = `🚫 High confidence — you are ${dist} m from the scan point and GPS is reliable. This delivery has been flagged for admin review.`;
    } else if (level === "Medium") {
      message = `⚠️ Medium GPS confidence — ${dist} m from scan point. GPS not fully reliable. Logged for review.`;
    } else {
      message = `⚠️ Low GPS confidence — ${dist} m from scan point. This delivery has been flagged for admin review.`;
    }

    return (
      <div style={{
        backgroundColor: isReject ? "#fee2e2" : "#fff3cd",
        border: `1px solid ${isReject ? "#f87171" : "#f59e0b"}`,
        borderRadius: "8px",
        padding: "12px 15px",
        marginBottom: "15px",
        fontSize: "0.85rem",
        color: isReject ? "#991b1b" : "#92400e",
        lineHeight: "1.5",
      }}>
        <strong>{message}</strong>
        <div style={{ marginTop: "5px", fontSize: "0.78rem", color: isReject ? "#7f1d1d" : "#78350f" }}>
          You can still upload and continue.
          {scanAcc != null && <span> &nbsp;|&nbsp; 📡 Scan: ±{scanAcc} m</span>}
          {photoAcc != null && <span> &nbsp;|&nbsp; 📸 Photo: ±{photoAcc} m</span>}
        </div>
      </div>
    );
  };

  /* ---------------- UI ---------------- */

  if (loading) return null;

  return (
    <div className="pc-card">
      <h3 className="pc-title">Capture Photo</h3>

      <input
        ref={fileInputRef}
        type="file"
        accept="image/*"
        capture="environment"
        onChange={(e) => handleFileSelect(e.target.files?.[0])}
        style={{ display: "none" }}
      />

      {cameraOpen && (
        <div className="pc-camera-preview">
          <video ref={videoRef} className="pc-video" autoPlay playsInline />
          <canvas ref={canvasRef} style={{ display: "none" }} />
          <button onClick={captureFromCamera}>Take Photo</button>
          <button onClick={stopCamera}>Cancel</button>
        </div>
      )}

      {/* --- Photo Preview --- */}
      {capturedImagePreview && !status && !cameraOpen && (
        <div style={{ textAlign: "center", marginTop: "20px" }}>
          {renderConfidenceBanner()}
          <img
            src={capturedImagePreview}
            alt="Captured preview"
            style={{ maxWidth: "100%", maxHeight: "400px", borderRadius: "8px", marginBottom: "15px" }}
          />
          <div style={{ display: "flex", gap: "10px", justifyContent: "center", flexWrap: "wrap" }}>
            <button
              onClick={handleUploadPhoto}
              style={{ backgroundColor: "#2e7d32", borderColor: "#2e7d32", color: "white" }}
            >
              Upload This Pic
            </button>
            <button onClick={openPicker}>Take Another Photo</button>
            <button onClick={callDoneCallback} style={{ backgroundColor: "#757575", borderColor: "#757575" }}>
              Back to Dashboard
            </button>
          </div>
        </div>
      )}

      {/* --- Idle (no photo yet) --- */}
      {!cameraOpen && !status && !capturedImagePreview && (
        <>
          <div style={{
            backgroundColor: "#e8f4fd",
            border: "1px solid #b3d9f2",
            borderRadius: "8px",
            padding: "12px 15px",
            marginBottom: "15px",
            fontSize: "0.85rem",
            color: "#1a5276",
            lineHeight: "1.4",
          }}>
            📍 <strong>GPS must be ON</strong> before taking the photo. Enable Location Tags in your camera settings.
          </div>
          <button onClick={openPicker}>Open Camera</button>
          <button
            onClick={callDoneCallback}
            style={{ marginTop: "10px", marginBottom: "20px", backgroundColor: "#757575", borderColor: "#757575" }}
          >
            Back to Dashboard
          </button>
        </>
      )}

      {/* --- In-progress statuses --- */}
      {status && status !== "error" && status !== "uploading" && status !== "uploaded" && (
        <>
          <div className="pc-status-message" style={{ textAlign: "center", marginTop: "10px", fontWeight: "bold" }}>
            Status: {status}
          </div>
          <button onClick={callDoneCallback} style={{ marginTop: "10px", marginBottom: "20px", backgroundColor: "#757575", borderColor: "#757575" }}>
            Back to Dashboard
          </button>
        </>
      )}

      {(status === "uploading" || status === "uploaded") && (
        <div className="pc-status-message" style={{ textAlign: "center", marginTop: "10px", fontWeight: "bold" }}>
          Status: {status}
        </div>
      )}

      {/* --- Error (incl. GPS denied) --- */}
      {status === "error" && (
        <div className="pc-error">
          <div style={{ marginBottom: "15px" }}>
            <strong>Location:</strong>
            <div style={{ marginTop: "5px", color: "#666" }}>{scanAddress}</div>
          </div>
          <div style={{ color: "#d32f2f", marginBottom: "15px", whiteSpace: "pre-line" }}>
            {errorMsg}
          </div>
          <div style={{ display: "flex", gap: "10px", justifyContent: "center" }}>
            <button onClick={handleTryAgain}>Try Again</button>
            <button onClick={callDoneCallback} style={{ backgroundColor: "#757575", borderColor: "#757575" }}>
              Back to Dashboard
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

PhotoCapture.propTypes = {
  userID: PropTypes.string.isRequired,
  uniqueKey: PropTypes.string.isRequired,
  onDone: PropTypes.func,
  onPhotoDone: PropTypes.func,
};
